using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace MemeManager {
 public partial class ManagerWindow {
  Window duplicateWindow;CancellationTokenSource duplicateCancellation;
  sealed class DuplicateRow {public int Group;public VisualSignature Item;public bool Anchor;}
  void ShowDuplicates(){if(duplicateWindow!=null){if(duplicateWindow.WindowState==WindowState.Minimized)duplicateWindow.WindowState=WindowState.Normal;duplicateWindow.Activate();return;}var dialog=Dialog("相似表情查重",850,710,false);dialog.ResizeMode=ResizeMode.CanResize;dialog.MinWidth=660;dialog.MinHeight=520;duplicateWindow=dialog;
   bool closed=false,busy=false;int page=0;const int pageSize=24;DuplicateResult result=null;string lastTrash=DuplicateTrash.Latest(library);var selected=new HashSet<string>();var rows=new List<DuplicateRow>();var previewPlayers=new List<GifPlayer>();
   var root=new Grid{Margin=new Thickness(20)};root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition());root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
   var heading=new StackPanel();heading.Children.Add(new TextBlock{Text="相似表情查重",FontSize=21,FontWeight=FontWeights.SemiBold,Foreground=BrushFor("Ink")});heading.Children.Add(new TextBlock{Text="优先保留已分组的副本 · 默认不选中 · 删除后可撤销",Foreground=BrushFor("Muted"),Margin=new Thickness(0,5,0,14)});root.Children.Add(heading);
   var controls=new WrapPanel{Margin=new Thickness(0,0,0,14)};var strictness=new ComboBox{Width=140,ItemsSource=new[]{"严格（推荐）","标准"},SelectedIndex=0,Margin=new Thickness(0,0,8,0)};var start=new Button{Content="开始检测",Background=BrushFor("Accent"),Foreground=Brushes.White,Margin=new Thickness(0,0,8,0)};var cancel=new Button{Content="取消检测",IsEnabled=false,Margin=new Thickness(0,0,12,0)};var summary=new TextBlock{Text="不会在后台自动扫描",Foreground=BrushFor("Muted"),VerticalAlignment=VerticalAlignment.Center,MaxWidth=340,TextWrapping=TextWrapping.Wrap};controls.Children.Add(strictness);controls.Children.Add(start);controls.Children.Add(cancel);controls.Children.Add(summary);Grid.SetRow(controls,1);root.Children.Add(controls);
   var tiles=new WrapPanel();var scroller=new ScrollViewer{Content=tiles,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroller,2);root.Children.Add(scroller);
   var bottom=new StackPanel();var note=new TextBlock{Text="相似不等于相同，请核对文字和动图。优先清理未分组副本；每组至少留一张，悬停 GIF 可预览。",Foreground=BrushFor("Muted"),TextWrapping=TextWrapping.Wrap,FontSize=11,Margin=new Thickness(0,10,0,10)};bottom.Children.Add(note);var actions=new WrapPanel();var prior=new Button{Content="‹",IsEnabled=false,Margin=new Thickness(0,0,4,0)};var next=new Button{Content="›",IsEnabled=false,Margin=new Thickness(0,0,10,0)};var pageLabel=new TextBlock{VerticalAlignment=VerticalAlignment.Center,Foreground=BrushFor("Muted"),Margin=new Thickness(0,0,12,0)};var selectSuggested=new Button{Content="选择建议删除项",IsEnabled=false,Margin=new Thickness(0,0,6,0)};var remove=new Button{Content="删除勾选",IsEnabled=false,Margin=new Thickness(0,0,6,0)};var all=new Button{Content="一键清理重复项",IsEnabled=false,Margin=new Thickness(0,0,6,0)};var undo=new Button{Content="撤销上次删除",IsEnabled=lastTrash!=null};foreach(var control in new UIElement[]{prior,next,pageLabel,selectSuggested,remove,all,undo})actions.Children.Add(control);bottom.Children.Add(actions);Grid.SetRow(bottom,3);root.Children.Add(bottom);dialog.Content=root;
   Action stopPreviews=()=>{foreach(var player in previewPlayers)player.Stop();previewPlayers.Clear();};
   Action render=null;render=()=>{stopPreviews();tiles.Children.Clear();int pages=Math.Max(1,(rows.Count+pageSize-1)/pageSize);page=Math.Max(0,Math.Min(page,pages-1));pageLabel.Text=(page+1)+" / "+pages+" 页";prior.IsEnabled=!busy&&page>0;next.IsEnabled=!busy&&page+1<pages;remove.Content="删除勾选（"+selected.Count+"）";remove.IsEnabled=!busy&&selected.Count>0;all.IsEnabled=selectSuggested.IsEnabled=!busy&&rows.Count>0;
    foreach(var row in rows.Skip(page*pageSize).Take(pageSize)){var meme=library.Data.Memes.FirstOrDefault(x=>x.Id==row.Item.Meme.Id);if(meme==null)continue;var image=new Image{Source=Thumbnail(meme),Width=154,Height=116,Stretch=Stretch.Uniform,Margin=new Thickness(0,7,0,6)};var check=new CheckBox{Content="选择删除",IsChecked=selected.Contains(meme.Id),Foreground=row.Anchor?BrushFor("Accent"):BrushFor("Ink")};check.Checked+=(s,e)=>{selected.Add(meme.Id);remove.Content="删除勾选（"+selected.Count+"）";remove.IsEnabled=!busy&&selected.Count>0;};check.Unchecked+=(s,e)=>{selected.Remove(meme.Id);remove.Content="删除勾选（"+selected.Count+"）";remove.IsEnabled=!busy&&selected.Count>0;};
     var panel=new StackPanel();panel.Children.Add(new TextBlock{Text="相似组 "+(row.Group+1)+(row.Anchor?" · 建议保留":"")+(row.Item.Frames>1?" · GIF":""),FontSize=10,Foreground=BrushFor(row.Anchor?"Accent":"Muted")});panel.Children.Add(image);panel.Children.Add(new TextBlock{Text=meme.Name,TextTrimming=TextTrimming.CharacterEllipsis,Foreground=BrushFor("Ink"),ToolTip=meme.Name});panel.Children.Add(new TextBlock{Text=row.Item.Width+" × "+row.Item.Height+" · 使用 "+meme.Uses+" 次",FontSize=10,Foreground=BrushFor("Muted"),Margin=new Thickness(0,3,0,4)});panel.Children.Add(new TextBlock{Text=Grouping.IsGrouped(meme)?string.Join("、",meme.GroupIds.Select(id=>Grouping.Path(library.Data.Groups,id))):(row.Anchor?"未分组（本组保留）":"未分组 · 优先清理"),TextTrimming=TextTrimming.CharacterEllipsis,FontSize=10,Foreground=BrushFor(Grouping.IsGrouped(meme)?"Muted":"Accent"),Margin=new Thickness(0,0,0,7)});panel.Children.Add(check);
     var tile=new Border{Child=panel,Width=180,Padding=new Thickness(10),Margin=new Thickness(0,0,9,9),CornerRadius=new CornerRadius(6),Background=BrushFor("Surface"),BorderBrush=BrushFor(row.Anchor?"Accent":"Line"),BorderThickness=new Thickness(1)};
     if(meme.Extension==".gif"){GifPlayer player=null;tile.MouseEnter+=(s,e)=>{if(player==null){player=new GifPlayer(image,library.FileFor(meme));previewPlayers.Add(player);player.Start();}};tile.MouseLeave+=(s,e)=>{if(player!=null){player.Stop();previewPlayers.Remove(player);player=null;}};}tiles.Children.Add(tile);
    }scroller.ScrollToTop();
   };
   Action refreshRows=()=>{rows.Clear();if(result!=null)for(int g=0;g<result.Groups.Count;g++){var remaining=result.Groups[g].Items.Where(x=>library.Data.Memes.Any(m=>m.Id==x.Meme.Id)).OrderByDescending(x=>Grouping.IsGrouped(library.Data.Memes.First(m=>m.Id==x.Meme.Id))).ThenByDescending(x=>library.Data.Memes.First(m=>m.Id==x.Meme.Id).Uses).ThenByDescending(x=>(long)x.Width*x.Height).ToList();if(remaining.Count<2)continue;for(int i=0;i<remaining.Count;i++)rows.Add(new DuplicateRow{Group=g,Item=remaining[i],Anchor=i==0});}selected.Clear();page=0;render();};
   Action<IEnumerable<string>> delete=ids=>{try{if(importing){summary.Text="导入尚未完成，请稍后清理。";return;}var chosen=new HashSet<string>(ids);chosen.IntersectWith(library.Data.Memes.Select(x=>x.Id));if(chosen.Count==0){refreshRows();return;}
    foreach(var group in result.Groups){var current=group.Items.Where(x=>library.Data.Memes.Any(m=>m.Id==x.Meme.Id)).ToList();if(current.Count>0&&current.All(x=>chosen.Contains(x.Meme.Id))){MessageBox.Show(dialog,"每个相似组至少保留一张，请取消勾选其中一张。","请保留原图");return;}}
    if(MessageBox.Show(dialog,"将 "+chosen.Count+" 张表情移至资料库回收区？\n感知哈希可能将不同文字的表情判为相似，请确认已核对预览。\n不会删除当初导入的源文件。","确认清理",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;
    var keepers=new Dictionary<string,string>();foreach(var group in result.Groups){var remaining=group.Items.Where(x=>!chosen.Contains(x.Meme.Id)&&library.Data.Memes.Any(m=>m.Id==x.Meme.Id)).OrderByDescending(x=>Grouping.IsGrouped(library.Data.Memes.First(m=>m.Id==x.Meme.Id))).ThenByDescending(x=>x.Meme.Uses).ToList();if(remaining.Count>0)foreach(var removed in group.Items.Where(x=>chosen.Contains(x.Meme.Id)))keepers[removed.Meme.Id]=remaining[0].Meme.Id;}stopPreviews();lastTrash=DuplicateTrash.Remove(library,chosen,keepers);undo.IsEnabled=lastTrash!=null;thumbnails.Clear();RefreshNavigation();Refresh();if(picker!=null&&picker.IsVisible)RefreshPicker();summary.Text="已移至回收区 "+chosen.Count+" 张，可撤销本次操作。";refreshRows();
   }catch(Exception ex){MessageBox.Show(dialog,ex.Message,"清理未完成");}};
   prior.Click+=(s,e)=>{page--;render();};next.Click+=(s,e)=>{page++;render();};selectSuggested.Click+=(s,e)=>{refreshRows();selected.Clear();foreach(var row in rows.Where(x=>!x.Anchor))selected.Add(row.Item.Meme.Id);render();};remove.Click+=(s,e)=>delete(selected.ToArray());all.Click+=(s,e)=>{refreshRows();delete(rows.Where(x=>!x.Anchor).Select(x=>x.Item.Meme.Id).ToArray());};
   undo.Click+=(s,e)=>{try{if(importing){summary.Text="请等待当前导入完成。";return;}int restored=DuplicateTrash.Restore(library,lastTrash);lastTrash=null;undo.IsEnabled=false;RefreshNavigation();Refresh();if(picker!=null&&picker.IsVisible)RefreshPicker();summary.Text="已恢复 "+restored+" 张表情。";refreshRows();}catch(Exception ex){MessageBox.Show(dialog,ex.Message,"恢复未完成");}};
   cancel.Click+=(s,e)=>{if(duplicateCancellation!=null)duplicateCancellation.Cancel();cancel.IsEnabled=false;summary.Text="正在停止检测…";};
   start.Click+=async(s,e)=>{if(busy)return;busy=true;start.IsEnabled=false;strictness.IsEnabled=false;cancel.IsEnabled=true;undo.IsEnabled=false;result=null;selected.Clear();rows.Clear();render();summary.Text="正在计算图片特征…";duplicateCancellation=new CancellationTokenSource();var cancellation=duplicateCancellation;var snapshot=library.Data.Memes.Select(x=>new Meme{Id=x.Id,Name=x.Name,Extension=x.Extension,Uses=x.Uses,Added=x.Added,GroupIds=x.GroupIds.ToList()}).ToList();int threshold=strictness.SelectedIndex==0?4:8;
    try{var scan=await Task.Run(()=>DuplicateScanner.Scan(library.Root,snapshot,threshold,cancellation.Token,(done,total)=>dialog.Dispatcher.BeginInvoke(new Action(()=>{if(!closed&&busy)summary.Text="已检测 "+done+" / "+total+" 张";}))));if(closed)return;result=scan;summary.Text="发现 "+scan.Groups.Count+" 组相似图片 · 跳过 "+scan.Skipped+" 张";summary.ToolTip="跳过项包括无法读取的文件、过大的图片及暂不参与近似查重的动态 PNG / WebP。";}
    catch(OperationCanceledException){if(!closed)summary.Text="已取消检测，未修改任何表情。";}catch(Exception ex){if(!closed)summary.Text="检测失败："+ex.Message;}
    finally{cancellation.Dispose();if(duplicateCancellation==cancellation)duplicateCancellation=null;busy=false;if(!closed){start.IsEnabled=true;strictness.IsEnabled=true;cancel.IsEnabled=false;undo.IsEnabled=lastTrash!=null;refreshRows();}}
   };
   dialog.StateChanged+=(s,e)=>{if(dialog.WindowState==WindowState.Minimized)stopPreviews();};dialog.Closed+=(s,e)=>{closed=true;if(duplicateCancellation!=null)duplicateCancellation.Cancel();stopPreviews();tiles.Children.Clear();thumbnails.Clear();duplicateWindow=null;};render();dialog.Show();
  }
 }
}
